    func encodedByteCount() throws(GesWireError) -> Int {
        let paths = Self.__paths
        let at = 0
        if (UInt64(rawValue) >> 26) != 0 { throw GesWireError(code: GesWireError.outOfRange, path: "") }
        if ((UInt64(rawValue) >> 0) & 15) > 9 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 1]) }
        if ((UInt64(rawValue) >> 5) & 3) > 2 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 3]) }
        if ((UInt64(rawValue) >> 7) & 15) > 10 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 4]) }
        if ((UInt64(rawValue) >> 13) & 15) > 9 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 7]) }
        if ((UInt64(rawValue) >> 18) & 3) > 2 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 9]) }
        if ((UInt64(rawValue) >> 20) & 15) > 10 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 10]) }
        return 4
    }

    /// Writes the record into a new array of its size.
    /// - Throws: `GesWireError` when a word taken unchecked holds an invalid field.
    func encoded() throws(GesWireError) -> [UInt8] {
        let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: 4, alignment: 8)
        defer { buffer.deallocate() }
        let count = try write(into: buffer)
        return Array(buffer[0..<count])
    }

    /// Reads a record from untrusted data into this instance and returns the number of bytes it occupies.
    /// - Throws: `GesWireError` when the data is no valid record.
    @discardableResult
    mutating func read(from data: UnsafeRawBufferPointer, byteLimit: Int = .max) throws(GesWireError) -> Int {
        var reader = GesBitReader(data: data, byteLimit: byteLimit)
        let paths = Self.__paths
        let at = 0
        var word: UInt64 = 0
        do {
            let field = try reader.read(4, path: paths[at + 1])
            if field > 9 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 1]) }
            word |= field << 0
        }
        word |= try reader.read(1, path: paths[at + 2]) << 4
        do {
            let field = try reader.read(2, path: paths[at + 3])
            if field > 2 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 3]) }
            word |= field << 5
        }
        do {
            let field = try reader.read(4, path: paths[at + 4])
            if field > 10 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 4]) }
            word |= field << 7
        }
        word |= try reader.read(2, path: paths[at + 5]) << 11
        do {
            let field = try reader.read(4, path: paths[at + 7])
            if field > 9 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 7]) }
            word |= field << 13
        }
        word |= try reader.read(1, path: paths[at + 8]) << 17
        do {
            let field = try reader.read(2, path: paths[at + 9])
            if field > 2 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 9]) }
            word |= field << 18
        }
        do {
            let field = try reader.read(4, path: paths[at + 10])
            if field > 10 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 10]) }
            word |= field << 20
        }
        word |= try reader.read(2, path: paths[at + 11]) << 24
        self = Self(uncheckedRawValue: UInt32(truncatingIfNeeded: word))
        return try reader.finish()
    }

    /// Reads a record from bytes into this instance and returns the number of bytes it occupies.
    /// - Throws: `GesWireError` when the bytes are no valid record.
    @discardableResult
    mutating func read(from bytes: [UInt8], byteLimit: Int = .max) throws(GesWireError) -> Int {
        let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(bytes.count, 1), alignment: 8)
        defer { buffer.deallocate() }
        buffer.copyBytes(from: bytes)
        return try read(from: UnsafeRawBufferPointer(rebasing: buffer[0..<bytes.count]), byteLimit: byteLimit)
    }

    /// Whether another record writes the same bytes: whether the words are equal.
    func wireEquals(_ other: Self) -> Bool { rawValue == other.rawValue }

    /// Copies another record's word.
    mutating func copy(from other: Self) { self = other }

    /// Does nothing: a packed record holds only values its fields encode.
    func quantize() {}

    /// Writes the delta against a baseline: a change bit and, when the words differ, the record's word.
    /// - Throws: `GesWireError` when a word taken unchecked holds an invalid field or the buffer is too small.
    func writeDelta(against baseline: Self, into buffer: UnsafeMutableRawBufferPointer) throws(GesWireError) -> Int {
        var writer = GesBitWriter(into: buffer)
        let paths = Self.__paths
        let at = 0
        if rawValue == baseline.rawValue {
            try writer.write(0, width: 1)
        } else {
            try writer.write(1, width: 1)
            if (UInt64(self.rawValue) >> 26) != 0 { throw GesWireError(code: GesWireError.outOfRange, path: "") }
            if ((UInt64(self.rawValue) >> 0) & 15) > 9 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 1]) }
            if ((UInt64(self.rawValue) >> 5) & 3) > 2 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 3]) }
            if ((UInt64(self.rawValue) >> 7) & 15) > 10 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 4]) }
            if ((UInt64(self.rawValue) >> 13) & 15) > 9 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 7]) }
            if ((UInt64(self.rawValue) >> 18) & 3) > 2 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 9]) }
            if ((UInt64(self.rawValue) >> 20) & 15) > 10 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 10]) }
            try writer.write(UInt64(self.rawValue), width: 26)
        }
        return try writer.finish()
    }

    /// Counts the bytes of the delta against a baseline.
    func deltaEncodedByteCount(against baseline: Self) -> Int { rawValue == baseline.rawValue ? 1 : (26 + 8) / 8 }

    /// Writes the delta against a baseline into a new array of its size.
    /// - Throws: `GesWireError` when a word taken unchecked holds an invalid field.
    func deltaEncoded(against baseline: Self) throws(GesWireError) -> [UInt8] {
        let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: deltaEncodedByteCount(against: baseline), alignment: 8)
        defer { buffer.deallocate() }
        let count = try writeDelta(against: baseline, into: buffer)
        return Array(buffer[0..<count])
    }

    /// Reads a delta against a baseline into this instance and returns the number of bytes it occupies.
    /// - Throws: `GesWireError` when the data is no valid delta, such as a word equal to the baseline's.
    @discardableResult
    mutating func readDelta(from data: UnsafeRawBufferPointer, against baseline: Self, byteLimit: Int = .max) throws(GesWireError) -> Int {
        var reader = GesBitReader(data: data, byteLimit: byteLimit)
        let paths = Self.__paths
        let at = 0
        if try reader.read(1, path: "") == 0 {
            self = baseline
        } else {
            var word: UInt64 = 0
            do {
                let field = try reader.read(4, path: paths[at + 1])
                if field > 9 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 1]) }
                word |= field << 0
            }
            word |= try reader.read(1, path: paths[at + 2]) << 4
            do {
                let field = try reader.read(2, path: paths[at + 3])
                if field > 2 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 3]) }
                word |= field << 5
            }
            do {
                let field = try reader.read(4, path: paths[at + 4])
                if field > 10 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 4]) }
                word |= field << 7
            }
            word |= try reader.read(2, path: paths[at + 5]) << 11
            do {
                let field = try reader.read(4, path: paths[at + 7])
                if field > 9 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 7]) }
                word |= field << 13
            }
            word |= try reader.read(1, path: paths[at + 8]) << 17
            do {
                let field = try reader.read(2, path: paths[at + 9])
                if field > 2 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 9]) }
                word |= field << 18
            }
            do {
                let field = try reader.read(4, path: paths[at + 10])
                if field > 10 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 10]) }
                word |= field << 20
            }
            word |= try reader.read(2, path: paths[at + 11]) << 24
            if UInt32(truncatingIfNeeded: word) == baseline.rawValue { throw GesWireError(code: GesWireError.invalidDelta, path: "") }
            self = Self(uncheckedRawValue: UInt32(truncatingIfNeeded: word))
        }
        return try reader.finish()
    }

    /// Reads a delta from bytes against a baseline into this instance and returns the number of bytes it occupies.
    /// - Throws: `GesWireError` when the bytes are no valid delta.
    @discardableResult
    mutating func readDelta(from bytes: [UInt8], against baseline: Self, byteLimit: Int = .max) throws(GesWireError) -> Int {
        let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(bytes.count, 1), alignment: 8)
        defer { buffer.deallocate() }
        buffer.copyBytes(from: bytes)
        return try readDelta(from: UnsafeRawBufferPointer(rebasing: buffer[0..<bytes.count]), against: baseline, byteLimit: byteLimit)
    }
}
